temp_marco_2021.sql:
SELECT COUNT(*) AS total
FROM internacoes
WHERE year(DT_SAIDA) = 2021 AND month(DT_SAIDA) = 3;

temp_intervalo_2015_2019.sql:
SELECT COUNT(*) AS total
FROM internacoes
WHERE year(DT_SAIDA) BETWEEN 2015 AND 2019;

demo_mulheres_2019.sql:
SELECT COUNT(*) AS total
FROM internacoes
WHERE SEXO IN (2, 3) AND year(DT_SAIDA) = 2019;

demo_homens_idosos.sql:
SELECT COUNT(*) AS total
FROM internacoes
WHERE SEXO = 1 AND IDADE >= 60;

cid_infarto_2023.sql:
SELECT COUNT(*) AS total
FROM internacoes
WHERE DIAG_PRINC LIKE 'I21%' AND year(DT_SAIDA) = 2023;

cid_diabetes_permanencia.sql:
SELECT ROUND(AVG(DIAS_PERM), 4) AS media_dias
FROM internacoes
WHERE DIAG_PRINC >= 'E10' AND DIAG_PRINC < 'E15';

multi_permanencia_longa.sql:
SELECT COUNT(*) AS internacoes, ROUND(AVG(VAL_TOT), 4) AS custo_medio
FROM internacoes
WHERE DIAS_PERM > 30;

gt_gt043.sql:
SELECT COUNT(*) AS com_ambos_diagnosticos
FROM internacoes
WHERE DIAG_SECUN <> '0';

gt_gt098.sql:
SELECT COUNT(*) AS total_municipios
FROM municipios
WHERE try_cast(SG_UF AS INTEGER) IS NULL AND SG_UF <> 'NA';

gt_gt103.sql:
SELECT COUNT(DISTINCT m.SG_UF) AS total_estados
FROM internacoes i
JOIN municipios m ON i.MUNIC_RES = m.CO_MUNICIPIO_6D;

gt_gt167.sql:
SELECT COUNT(*) AS internacoes_com_cbor
FROM internacoes
WHERE CBOR <> '000000';
